import re, pathlib
f='.skilled/skills/sk-doc/sk-create-quality-control/references/transformation-patterns.md'
lines=pathlib.Path(f).read_text().splitlines()
in_fence=None
for i,l in enumerate(lines,1):
    m=re.match(r'^(`{3,})(.*)$',l)
    if m:
        if in_fence is None:
            in_fence=(len(m.group(1)),i,m.group(2))
            print(f'{i}: FENCE OPEN {m.group(1)!r}{m.group(2)!r}')
        elif len(m.group(1))>=in_fence[0] and not m.group(2).strip():
            print(f'{i}: FENCE CLOSE (opened {in_fence[1]})')
            in_fence=None
        continue
    if in_fence is None and l.startswith('#'):
        print(f'{i}: {l}')
